// Encrypted precompute (CORE-1963, ADR-0235). An Unsealed Encrypted Library's
// renditions are generated by a server-owned job through the shared
// encrypted-derivative helper: the source is decrypted only onto the helper's
// loopback endpoint, FFmpeg writes one fragmented MP4 to stdout, and the
// generator segments it in memory and encrypts every member (init, segments,
// playlists) under the rendition's object context before it reaches disk.
// Staging holds only ciphertext, and publication is the same rename-then-CAS
// as the public path. The rendition row lives in the Library's own DB, so it
// is unreachable while the Library is Sealed, and its ID carries no content
// fingerprint.

const (
	// PrecomputeSegmentSeconds is the target duration of one precomputed HLS
	// segment; key frames are forced on this grid.
	PrecomputeSegmentSeconds = 4
	// PrecomputeToneMapMarker is the rung-directory member that records a
	// rendition was tone-mapped to SDR.
	PrecomputeToneMapMarker = toneMappedSDRMarker

	encryptedPrecomputeIDPrefix = "precompute-enc:"
	encryptedPrecomputeDir      = ".precompute-encrypted"
)

var (
	// ErrPrecomputeEncrypted refuses a job whose Library's encryption does
	// not match its payload, or that this server cannot generate on the
	// encrypted plane (no generator, or a composed rung).
	ErrPrecomputeEncrypted = errors.New("precompute refused for an Encrypted Library")
	// ErrPrecomputeSealed stops an encrypted precompute once its Library is
	// Sealed.
	ErrPrecomputeSealed = errors.New("encrypted library is sealed")
)

// EncryptedPrecomputeSpec is one encrypted rendition generation. OutputDir is
// the staging directory the generator fills with ciphertext members only.
// StageDir and StageName place the helper's ephemeral-key stage file, MaxBytes
// bounds the transcode output, and Revoked must be polled while generating.
type EncryptedPrecomputeSpec struct {
	PrecomputeSpec
	LibraryID       store.LibraryID
	DurationSeconds int
	StageDir        string
	StageName       string
	MaxBytes        int64
	Revoked         func(context.Context) error
}

// EncryptedPrecomputeGenerator is the app-owned seam for the encrypted plane;
// playback cannot reach the crypto layer or the helper directly.
type EncryptedPrecomputeGenerator interface {
	// PrecomputeEncryptedHLS writes master.m3u8 and <rung>/{index.m3u8,
	// init.mp4, *.m4s} into spec.OutputDir, each encrypted under
	// PrecomputeMemberObjectID(spec.RenditionID, name).
	PrecomputeEncryptedHLS(ctx context.Context, spec EncryptedPrecomputeSpec) error
	// DecryptPrecomputeMember returns the plaintext of the member name
	// (slash-separated, relative to the generation) stored at ciphertextPath,
	// in memory.
	DecryptPrecomputeMember(libraryID store.LibraryID, renditionID store.PlaybackRenditionID, name, ciphertextPath string) ([]byte, error)
	// IsPrecomputeCiphertext reports whether r starts with the encrypted
	// object header.
	IsPrecomputeCiphertext(r io.Reader) (bool, error)
}

// PrecomputeSegment is one media segment of a precomputed rung playlist.
type PrecomputeSegment struct {
	URI      string
	Duration time.Duration
}

// EncryptedPrecomputeRenditionID is the rendition identity of an encrypted
// precompute. Unlike PrecomputeRenditionID it carries no content fingerprint:
// the ID reaches the shared job table and stream tokens.
func EncryptedPrecomputeRenditionID(mediaID store.MediaID, rungID string) store.PlaybackRenditionID {
	return store.PlaybackRenditionID(encryptedPrecomputeIDPrefix + string(mediaID) + ":" + rungID)
}

// IsEncryptedPrecomputeRenditionID reports whether id names an encrypted
// precompute.
func IsEncryptedPrecomputeRenditionID(id store.PlaybackRenditionID) bool {
	return strings.HasPrefix(string(id), encryptedPrecomputeIDPrefix)
}

// PrecomputeMemberObjectID is the immutable object identity one member of a
// rendition is encrypted under: the rendition row id plus the member's
// slash-separated name within it, never its file path.
func PrecomputeMemberObjectID(id store.PlaybackRenditionID, name string) string {
	return "playback-rendition/" + string(id) + "/" + name
}

// Rendition is the FFmpeg encode a precomputed rung uses, shared by the public
// and encrypted generators.
func (spec PrecomputeSpec) Rendition() ffmpeg.Rendition {
	return ffmpeg.Rendition{
		Height:         spec.Height,
		VideoKbps:      precomputeVideoKbps(spec.Bandwidth),
		AudioCodec:     "aac",
		AudioChannels:  2,
		ColorTransfer:  spec.SourceVideo.ColorTransfer,
		ColorPrimaries: spec.SourceVideo.ColorPrimaries,
		DoViProfile:    spec.SourceVideo.DoViProfile,
		DoViBLCompatID: spec.SourceVideo.DoViBLCompatID,

		SourceVideoCodec:    spec.SourceVideo.Codec,
		SourceVideoBitDepth: spec.SourceVideo.BitDepth,
	}
}

// PrecomputeMasterPlaylist is a rendition's master playlist: one variant, the
// rung's media playlist.
func PrecomputeMasterPlaylist(spec PrecomputeSpec) []byte {
	var b strings.Builder
	b.WriteString("#EXTM3U\n")
	b.WriteString("#EXT-X-VERSION:7\n")
	fmt.Fprintf(&b, "#EXT-X-STREAM-INF:BANDWIDTH=%d,CODECS=\"avc1.64001f,mp4a.40.2\"\n", spec.Bandwidth)
	fmt.Fprintf(&b, "%s/index.m3u8\n", spec.RungID)
	return []byte(b.String())
}

// PrecomputeMediaPlaylist is a finished fMP4 VOD media playlist over segments,
// with init.mp4 as the initialization section.
func PrecomputeMediaPlaylist(segments []PrecomputeSegment) []byte {
	target := 1
	for _, segment := range segments {
		if seconds := int(math.Ceil(segment.Duration.Seconds())); seconds > target {
			target = seconds
		}
	}
	var b strings.Builder
	b.WriteString("#EXTM3U\n")
	b.WriteString("#EXT-X-VERSION:7\n")
	fmt.Fprintf(&b, "#EXT-X-TARGETDURATION:%d\n", target)
	b.WriteString("#EXT-X-MEDIA-SEQUENCE:0\n")
	b.WriteString("#EXT-X-PLAYLIST-TYPE:VOD\n")
	b.WriteString("#EXT-X-INDEPENDENT-SEGMENTS\n")
	b.WriteString("#EXT-X-MAP:URI=\"init.mp4\"\n")
	for _, segment := range segments {
		fmt.Fprintf(&b, "#EXTINF:%.6f,\n%s\n", segment.Duration.Seconds(), segment.URI)
	}
	b.WriteString("#EXT-X-ENDLIST\n")
	return []byte(b.String())
}

// PurgeEncryptedPrecomputedRenditions removes every encrypted rendition of one
// Library. The ciphertext is regenerable, so a rewrap purges it instead of
// rewrapping it; it runs while the Library is Sealed and so never touches the
// Library's DB. An empty cache root is a no-op.
//
// The removal resolves through a descriptor on the cache root and refuses a
// symlinked encrypted-precompute directory, so a planted link can never turn
// it into a removal outside the cache.
func PurgeEncryptedPrecomputedRenditions(cacheRoot string, libraryID store.LibraryID) error {
	if strings.TrimSpace(cacheRoot) == "" || libraryID == "" {
		return nil
	}
	root, err := os.OpenRoot(cacheRoot)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	defer root.Close()
	if err := rejectSymlinkedDir(root, encryptedPrecomputeDir); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	return root.RemoveAll(encryptedPrecomputeLibraryRel(libraryID))
}

// ReconcileEncryptedPrecomputedRenditions is the unseal-time sweep of one
// Library's encrypted precompute tree (ADR-0235). A generation survives only
// when it is a validly named directory under a validly named Media directory
// and every member in it is a non-empty regular file that starts with a
// libencrypt object header (isCiphertext). Any other generation (one holding a
// plaintext, empty, linked or special member) is removed whole, as is every
// stray entry at the Library or Media level. A missing tree is a no-op. Every
// inspection and removal error is joined and returned, so the caller fails the
// unseal closed.
func ReconcileEncryptedPrecomputedRenditions(cacheRoot string, libraryID store.LibraryID, isCiphertext func(io.Reader) (bool, error)) error {
	if strings.TrimSpace(cacheRoot) == "" {
		return nil
	}
	if libraryID == "" || isCiphertext == nil {
		return errors.New("encrypted precompute reconcile needs a library and a ciphertext check")
	}
	root, err := os.OpenRoot(cacheRoot)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	defer root.Close()
	rel := encryptedPrecomputeLibraryRel(libraryID)
	if err := rejectSymlinkedDir(root, rel); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	library, err := root.OpenRoot(rel)
	if err != nil {
		return err
	}
	defer library.Close()
	mediaDirs, err := fs.ReadDir(library.FS(), ".")
	if err != nil {
		return err
	}
	var joined error
	for _, mediaDir := range mediaDirs {
		name := mediaDir.Name()
		if !mediaDir.IsDir() || !lowerHexName(name, 0) {
			joined = errors.Join(joined, removeRootedEntry(library, name))
			continue
		}
		joined = errors.Join(joined, reconcileEncryptedPrecomputeMedia(library, name, isCiphertext))
	}
	return joined
}

func reconcileEncryptedPrecomputeMedia(library *os.Root, mediaDir string, isCiphertext func(io.Reader) (bool, error)) error {
	media, err := library.OpenRoot(mediaDir)
	if err != nil {
		return err
	}
	defer media.Close()
	generations, err := fs.ReadDir(media.FS(), ".")
	if err != nil {
		return err
	}
	var joined error
	for _, generation := range generations {
		name := generation.Name()
		if generation.IsDir() && lowerHexName(name, 64) {
			keep, err := encryptedPrecomputeGenerationIsCiphertext(media, name, isCiphertext)
			if err != nil {
				joined = errors.Join(joined, err)
				continue
			}
			if keep {
				continue
			}
		}
		joined = errors.Join(joined, removeRootedEntry(media, name))
	}
	return joined
}

// encryptedPrecomputeGenerationIsCiphertext reports whether every member of a
// generation is a non-empty regular ciphertext file. A non-nil error means the
// generation could not be inspected; the generation is then left in place and
// the error fails the reconcile closed.
func encryptedPrecomputeGenerationIsCiphertext(media *os.Root, name string, isCiphertext func(io.Reader) (bool, error)) (bool, error) {
	generation, err := media.OpenRoot(name)
	if err != nil {
		return false, err
	}
	defer generation.Close()
	members := 0
	clean := true
	err = fs.WalkDir(generation.FS(), ".", func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			return nil
		}
		if !entry.Type().IsRegular() {
			clean = false
			return fs.SkipAll
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		if info.Size() == 0 {
			clean = false
			return fs.SkipAll
		}
		file, err := generation.Open(path)
		if err != nil {
			return err
		}
		ok, err := isCiphertext(file)
		closeErr := file.Close()
		if err != nil {
			return err
		}
		if closeErr != nil {
			return closeErr
		}
		if !ok {
			clean = false
			return fs.SkipAll
		}
		members++
		return nil
	})
	if err != nil {
		return false, err
	}
	return clean && members > 0, nil
}

func encryptedPrecomputeLibraryRel(libraryID store.LibraryID) string {
	return filepath.Join(encryptedPrecomputeDir, fmt.Sprintf("%x", []byte(libraryID)))
}

// lowerHexName reports whether name is lowercase hex, of exactly size
// characters when size is positive.
func lowerHexName(name string, size int) bool {
	if name == "" || len(name)%2 != 0 || (size > 0 && len(name) != size) {
		return false
	}
	for _, r := range name {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return false
		}
	}
	return true
}

// rejectSymlinkedDir fails unless every component of rel is a real directory
// inside root: Lstat never follows the final link, so a planted symlink at any
// level is refused rather than resolved.
func rejectSymlinkedDir(root *os.Root, rel string) error {
	walked := ""
	for _, part := range strings.Split(filepath.ToSlash(rel), "/") {
		walked = filepath.Join(walked, part)
		info, err := root.Lstat(walked)
		if err != nil {
			return err
		}
		if !info.IsDir() {
			return fmt.Errorf("encrypted precompute: %s is not a directory", filepath.ToSlash(walked))
		}
	}
	return nil
}

func removeRootedEntry(root *os.Root, name string) error {
	if err := root.RemoveAll(name); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

func encryptedPrecomputeRequest(req PrecomputeRequest, libraryID store.LibraryID, cacheRoot string) PrecomputeRequest {
	req.RenditionID = EncryptedPrecomputeRenditionID(req.MediaID, req.RungID)
	req.ContentFingerprint = ""
	req.SourcePath = ""
	req.LibraryID = libraryID
	req.Encrypted = true
	req.Path = filepath.Join(cacheRoot, string(req.RenditionID))
	return req
}

func validateEncryptedPrecomputeRequest(req PrecomputeRequest) error {
	switch {
	case req.LibraryID == "":
		return errors.New("encrypted precompute requires its library ID")
	case req.ContentFingerprint != "" || req.SourcePath != "":
		return errors.New("encrypted precompute payload must not carry the source identity")
	case req.RungID == ComposedRungID:
		return ErrPrecomputeEncrypted
	case req.RenditionID != EncryptedPrecomputeRenditionID(req.MediaID, req.RungID):
		return errors.New("encrypted precompute rendition ID does not match its media and rung")
	}
	return nil
}

// encryptedRun refuses a job this server must not run on the encrypted plane,
// reads the source identity from the Library's DB, and returns the run that
// generates, verifies and publishes ciphertext only.
func (h PrecomputeJobHandler) encryptedRun(ctx context.Context, req PrecomputeRequest, media store.Media, encrypted bool) (precomputeRun, PrecomputeRequest, error) {
	if !encrypted || !req.Encrypted || h.Encrypted == nil || h.Sealed == nil || req.LibraryID != media.LibraryID {
		return precomputeRun{}, req, ErrPrecomputeEncrypted
	}
	libraryID := req.LibraryID
	revoked := func(ctx context.Context) error {
		if err := ctx.Err(); err != nil {
			return err
		}
		if h.Sealed(libraryID) {
			return ErrPrecomputeSealed
		}
		return nil
	}
	if err := revoked(ctx); err != nil {
		return precomputeRun{}, req, err
	}
	files, err := h.Store.MediaFilesForMedia(ctx, req.MediaID, store.LibraryFilter{AllLibraries: true, Revealed: true})
	if err != nil {
		return precomputeRun{}, req, err
	}
	if len(files) == 0 {
		return precomputeRun{}, req, errors.New("media has no source files")
	}
	req.ContentFingerprint = files[0].ContentFingerprint
	req.SourcePath = files[0].Path

	gen := h.Encrypted
	renditionID := req.RenditionID
	read := func(artifactRoot *os.Root, name string) ([]byte, error) {
		// Lstat through the root first, so the path-based decrypt never
		// follows a link out of the generation.
		info, err := artifactRoot.Lstat(name)
		if err != nil {
			return nil, err
		}
		if !info.Mode().IsRegular() {
			return nil, fmt.Errorf("member %s is not a regular file", filepath.ToSlash(name))
		}
		return gen.DecryptPrecomputeMember(libraryID, renditionID, filepath.ToSlash(name), filepath.Join(artifactRoot.Name(), name))
	}
	member := func(artifactRoot *os.Root, name string) error {
		f, err := artifactRoot.Open(name)
		if err != nil {
			return err
		}
		defer f.Close()
		ok, err := gen.IsPrecomputeCiphertext(f)
		if err != nil {
			return err
		}
		if !ok {
			return fmt.Errorf("%w: member %s is not ciphertext", ErrPrecomputeIncomplete, filepath.ToSlash(name))
		}
		return nil
	}
	return precomputeRun{
		paths: encryptedPrecomputeGenerationPaths,
		generate: func(ctx context.Context, spec PrecomputeSpec, estimateBytes int64) error {
			return gen.PrecomputeEncryptedHLS(ctx, EncryptedPrecomputeSpec{
				PrecomputeSpec:  spec,
				LibraryID:       libraryID,
				DurationSeconds: media.DurationSeconds,
				StageDir:        filepath.Dir(spec.OutputDir),
				StageName:       strings.TrimSuffix(filepath.Base(spec.OutputDir), ".stage") + "-transcode",
				MaxBytes:        estimateBytes,
				Revoked:         revoked,
			})
		},
		verify: func(root, rungID string) error {
			return verifyPrecomputeArtifactWith(root, rungID, read, member)
		},
		revoked: revoked,
	}, req, nil
}

// encryptedPrecomputeGenerationPaths stages beside the public generations
// (the startup sweep clears that directory) and publishes under a per-Library
// encrypted root that the sweep leaves alone, so valid ciphertext survives a
// restart and a rewrap purges one Library with a single removal.
func encryptedPrecomputeGenerationPaths(req PrecomputeRequest, job store.Job, generation int64) (staging, published string) {
	staging, public := precomputeGenerationPaths(req, job, generation)
	cacheRoot := filepath.Dir(req.Path)
	published = filepath.Join(cacheRoot, encryptedPrecomputeDir,
		fmt.Sprintf("%x", []byte(req.LibraryID)), fmt.Sprintf("%x", []byte(req.MediaID)), filepath.Base(public))
	return staging, published
}
